    realtype AUX_VAR_H_CXCL12_Texcl = (SPVAR(SP_V_T_CXCL12) / AUX_VAR_V_T) / (PARAM(P_CXCL12_50_Texcl) + (SPVAR(SP_V_T_CXCL12) / AUX_VAR_V_T));

