    realtype AUX_VAR_H_IL6_M2 = (SPVAR(SP_V_T_IL6) / AUX_VAR_V_T) / (PARAM(P_IL6_50_M2) + (SPVAR(SP_V_T_IL6) / AUX_VAR_V_T));

